package br.com.erp.inventory;

import br.com.erp.auth.*;
import br.com.erp.purchase.*;
import br.com.erp.shared.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

@RestController @Validated @RequestMapping("/api/v1/inventory/replenishment") @PreAuthorize("hasAuthority('inventory:read')")
public class ReplenishmentController {
 private final ReplenishmentService service;public ReplenishmentController(ReplenishmentService service){this.service=service;}
 public record Policy(@NotNull UUID requestId,@NotNull UUID warehouseId,@NotNull UUID productId,@NotNull @Min(0) Long version,@NotNull @DecimalMin("0") @Digits(integer=13,fraction=6) BigDecimal minimum,@NotNull @DecimalMin("0") @Digits(integer=13,fraction=6) BigDecimal target){}
 public record Row(UUID productId,String sku,String name,String unit,String minimum,String target,String available,String suggested,String unitCost,long version){}
 public record Order(@NotNull UUID requestId,@NotNull UUID warehouseId,@NotNull UUID supplierId,@NotEmpty @Size(max=100) List<PurchaseContracts.@NotNull @Valid Item> items){}
 @GetMapping public Map<String,Object> list(@AuthenticationPrincipal Actor a,@RequestParam UUID warehouseId,@RequestParam(defaultValue="true") boolean onlyNeeded,@RequestParam(defaultValue="0") @Min(0) @Max(100000) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return service.list(a,warehouseId,onlyNeeded,page,size);}
 @PutMapping @PreAuthorize("hasAuthority('inventory:read') and hasAuthority('inventory:write')") public Map<String,Object> save(@AuthenticationPrincipal Actor a,@Valid @RequestBody Policy input){return service.save(a,input);}
 @PostMapping("/purchase-order") @PreAuthorize("hasAuthority('inventory:read') and hasAuthority('purchase:read') and hasAuthority('purchase:write')") public PurchaseContracts.Order order(@AuthenticationPrincipal Actor a,@Valid @RequestBody Order input){return service.order(a,input);}
}
@Service
class ReplenishmentService {
 private final JdbcTemplate db;private final BranchAccess access;private final WorkflowSupport flow;private final Audit audit;private final StockService stock;private final PurchaseService purchases;
 ReplenishmentService(JdbcTemplate db,BranchAccess access,WorkflowSupport flow,Audit audit,StockService stock,PurchaseService purchases){this.db=db;this.access=access;this.flow=flow;this.audit=audit;this.stock=stock;this.purchases=purchases;}
 private String available(){return "COALESCE(b.quantity,0)-COALESCE((SELECT SUM(lb.quantity) FROM stock_lot_balance lb JOIN stock_lot ll ON ll.tenant_id=lb.tenant_id AND ll.id=lb.lot_id WHERE lb.tenant_id=r.tenant_id AND lb.warehouse_id=r.warehouse_id AND ll.product_id=r.product_id AND ll.expires_on<?),0)";}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> list(Actor a,UUID warehouse,boolean needed,int page,int size){access.requireWarehouse(a,warehouse);LocalDate day=LocalDate.now(ZoneId.of("America/Sao_Paulo"));String base=" FROM replenishment_policy r JOIN product p ON p.tenant_id=r.tenant_id AND p.id=r.product_id LEFT JOIN stock_balance b ON b.tenant_id=r.tenant_id AND b.product_id=r.product_id AND b.warehouse_id=r.warehouse_id WHERE r.tenant_id=? AND r.warehouse_id=? AND p.active=TRUE";String query="SELECT x.* FROM (SELECT r.product_id,p.sku,p.name,p.unit,r.minimum_quantity,r.target_quantity,r.version,COALESCE(b.average_cost,0) AS unit_cost,"+available()+" AS available"+base+") x"+(needed?" WHERE x.available<x.minimum_quantity":"");var args=new ArrayList<Object>(List.of(day,a.tenantId(),warehouse));long total=db.queryForObject("SELECT COUNT(*) FROM ("+query+") q",Long.class,args.toArray());args.add(size);args.add((long)page*size);boolean costs=stock.canSeeCost(a);var rows=db.query(query+" ORDER BY x.name,x.product_id LIMIT ? OFFSET ?",(r,i)->new ReplenishmentController.Row(r.getObject("product_id",UUID.class),r.getString("sku"),r.getString("name"),r.getString("unit"),r.getBigDecimal("minimum_quantity").toPlainString(),r.getBigDecimal("target_quantity").toPlainString(),r.getBigDecimal("available").toPlainString(),r.getBigDecimal("target_quantity").subtract(r.getBigDecimal("available")).max(BigDecimal.ZERO).toPlainString(),costs?r.getBigDecimal("unit_cost").toPlainString():null,r.getLong("version")),args.toArray());return Map.of("items",rows,"total",total,"page",page,"size",size);}
 @Transactional public Map<String,Object> save(Actor a,ReplenishmentController.Policy input){flow.lock(a);access.requireWarehouse(a,input.warehouseId());if(input.target().compareTo(input.minimum())<0)throw flow.bad("Estoque alvo deve ser maior ou igual ao mínimo.");if(db.queryForObject("SELECT COUNT(*) FROM product WHERE tenant_id=? AND id=? AND active=TRUE",Long.class,a.tenantId(),input.productId())!=1)throw flow.missing("Produto ativo não encontrado.");String hash=flow.hash("REPLENISH_POLICY",input.warehouseId(),input.productId(),input.version(),input.minimum(),input.target());UUID replay=flow.replay(a,input.requestId(),"REPLENISH_POLICY",hash);if(replay!=null)return Map.of("productId",replay);var old=db.query("SELECT version FROM replenishment_policy WHERE tenant_id=? AND warehouse_id=? AND product_id=?",(r,i)->r.getLong(1),a.tenantId(),input.warehouseId(),input.productId());if(old.isEmpty()){if(input.version()!=0)throw flow.conflict("Política ainda não existe.");db.update("INSERT INTO replenishment_policy(tenant_id,warehouse_id,product_id,minimum_quantity,target_quantity,version) VALUES(?,?,?,?,?,1)",a.tenantId(),input.warehouseId(),input.productId(),input.minimum(),input.target());}else{if(old.getFirst()!=input.version().longValue())throw flow.conflict("Política alterada. Atualize.");db.update("UPDATE replenishment_policy SET minimum_quantity=?,target_quantity=?,version=version+1 WHERE tenant_id=? AND warehouse_id=? AND product_id=?",input.minimum(),input.target(),a.tenantId(),input.warehouseId(),input.productId());}flow.record(a,input.requestId(),"REPLENISH_POLICY",hash,input.productId());audit.record(a,"REPLENISHMENT_POLICY_CHANGED",input.productId());return Map.of("productId",input.productId());}
 @Transactional public PurchaseContracts.Order order(Actor a,ReplenishmentController.Order input){flow.lock(a);access.requireWarehouse(a,input.warehouseId());var fields=new ArrayList<Object>(List.of("REPLENISH_ORDER",input.warehouseId(),input.supplierId()));for(var l:input.items())Collections.addAll(fields,l.productId(),l.quantity(),l.unitCost());String hash=flow.hash(fields.toArray());UUID replay=flow.replay(a,input.requestId(),"REPLENISH_ORDER",hash);if(replay!=null)return purchases.get(a,replay);if(db.queryForObject("SELECT COUNT(*) FROM purchase_order WHERE tenant_id=? AND request_id=?",Long.class,a.tenantId(),input.requestId())>0)throw flow.conflict("Identificador já utilizado em compra.");var seen=new HashSet<UUID>();for(var l:input.items()){if(!seen.add(l.productId()))throw flow.bad("Produto repetido.");var policies=db.query("SELECT r.target_quantity,"+available()+" AS available,r.minimum_quantity FROM replenishment_policy r LEFT JOIN stock_balance b ON b.tenant_id=r.tenant_id AND b.warehouse_id=r.warehouse_id AND b.product_id=r.product_id WHERE r.tenant_id=? AND r.warehouse_id=? AND r.product_id=?",(r,i)->new BigDecimal[]{r.getBigDecimal(1),r.getBigDecimal(2),r.getBigDecimal(3)},LocalDate.now(ZoneId.of("America/Sao_Paulo")),a.tenantId(),input.warehouseId(),l.productId());if(policies.isEmpty()||policies.getFirst()[1].compareTo(policies.getFirst()[2])>=0||l.quantity().compareTo(policies.getFirst()[0].subtract(policies.getFirst()[1]))>0)throw flow.conflict("Necessidade mudou. Atualize as sugestões antes de criar o pedido.");}UUID branch=db.queryForObject("SELECT branch_id FROM warehouse WHERE tenant_id=? AND id=? AND active=TRUE",UUID.class,a.tenantId(),input.warehouseId());var result=purchases.create(a,new PurchaseContracts.Input(input.requestId(),branch,input.supplierId(),"Reposição do depósito "+input.warehouseId(),input.items()));flow.record(a,input.requestId(),"REPLENISH_ORDER",hash,result.header().id());return result;}
}
